const home=document.querySelector('#home');
const booth=document.querySelector('#booth');
const filters={original:'none',mono:'grayscale(1)',vintage:'sepia(.48) saturate(.7) contrast(.93)',rose:'sepia(.2) saturate(.75) hue-rotate(320deg)'};
const colors={cherry:['#a82e3e','#f5f2ea'],cream:['#faf6ea','#262a27'],ink:['#292b2a','#faf6ea'],blue:['#c1d6e3','#262a27']};
let activeFilter='original',activeColor='cherry',busy=false,countdownTimer;
document.querySelectorAll('[data-pairs]').forEach(container=>{for(let i=0;i<Number(container.dataset.pairs);i++){const pair=document.createElement('div');pair.className='photo-pair';['woman','man'].forEach(person=>{const img=document.createElement('img');img.src=`public/${person}.jpg`;img.alt='';img.loading='eager';pair.append(img)});container.append(pair)}});
function route(){const isBooth=location.hash==='#booth';home.hidden=isBooth;booth.hidden=!isBooth;document.querySelector('.home-nav').hidden=isBooth;document.querySelector('.nav-cta').hidden=isBooth;document.title=isBooth?'Your booth — Together':'Together — A little closer.';if(isBooth||!location.hash)window.scrollTo(0,0);if(!isBooth&&busy){clearTimeout(countdownTimer);finishCountdown(false)}}
window.addEventListener('hashchange',route);route();
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{activeFilter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('.camera-photo,.editor-strip .photo-pair img').forEach(img=>img.style.filter=filters[activeFilter])}));
document.querySelectorAll('[data-color]').forEach(button=>button.addEventListener('click',()=>{activeColor=button.dataset.color;document.querySelectorAll('[data-color]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});const strip=document.querySelector('.editor-strip');strip.style.background=colors[activeColor][0];strip.style.color=colors[activeColor][1]}));
document.querySelector('#caption').addEventListener('input',e=>document.querySelector('#caption-preview').textContent=e.target.value);
const capture=document.querySelector('#capture');const count=document.querySelector('#countdown');
function finishCountdown(completed){busy=false;count.hidden=true;capture.disabled=false;capture.innerHTML='Try again <span aria-hidden="true">◎</span>';if(completed){document.querySelector('#capture-hint').textContent='Cute, right? Customize your sample keepsake and save it.';const strip=document.querySelector('.editor-strip');strip.classList.remove('flash');void strip.offsetWidth;strip.classList.add('flash')}}
capture.addEventListener('click',()=>{if(busy)return;busy=true;capture.disabled=true;count.hidden=false;let n=3;count.textContent=n;document.querySelector('#capture-hint').textContent='A little practice. These are sample photos.';function tick(){n--;if(n>0){count.textContent=n;countdownTimer=setTimeout(tick,1000)}else finishCountdown(true)}countdownTimer=setTimeout(tick,1000)});
function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src})}
function crop(ctx,img,x,y,w,h,zoom=1){const ratio=Math.max(w/img.width,h/img.height)*zoom;const sw=w/ratio,sh=h/ratio;ctx.drawImage(img,(img.width-sw)/2,(img.height-sh)*.4,sw,sh,x,y,w,h)}
document.querySelector('#download').addEventListener('click',async()=>{const button=document.querySelector('#download'),status=document.querySelector('#save-status');button.disabled=true;status.textContent='Making your keepsake…';try{const pictures=await Promise.all([loadImage('public/woman.jpg'),loadImage('public/man.jpg')]);await document.fonts.ready;const canvas=document.createElement('canvas');canvas.width=720;canvas.height=1390;const ctx=canvas.getContext('2d');const [bg,fg]=colors[activeColor];ctx.fillStyle=bg;ctx.fillRect(0,0,720,1390);ctx.fillStyle=fg;ctx.font='600 24px "DM Sans", sans-serif';ctx.fillText('T O G E T H E R',40,58);ctx.font='30px Arial';ctx.fillText('♡',650,58);for(let i=0;i<3;i++){ctx.save();ctx.filter=filters[activeFilter];crop(ctx,pictures[0],40,88+i*358,314,332,i===1?1.13:i===2?1.06:1);crop(ctx,pictures[1],366,88+i*358,314,332,i===1?1.13:i===2?1.06:1);ctx.restore()}ctx.fillStyle=fg;ctx.textAlign='center';const caption=document.querySelector('#caption').value;let size=76;ctx.font=`italic ${size}px "Instrument Serif", Georgia, serif`;while(ctx.measureText(caption).width>640&&size>24){size--;ctx.font=`italic ${size}px "Instrument Serif", Georgia, serif`}ctx.fillText(caption,360,1260);ctx.font='17px "DM Sans", sans-serif';ctx.fillText('A LITTLE KEEPSAKE. A LOT OF LOVE.',360,1310);const format=document.querySelector('#format').value;const blob=await new Promise(resolve=>canvas.toBlob(resolve,`image/${format}`,.95));if(!blob)throw Error('Export failed');const url=URL.createObjectURL(blob);const link=document.createElement('a');link.download=`together-sample.${format==='jpeg'?'jpg':'png'}`;link.href=url;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status.textContent='Your sample strip is ready. A little closer, already.'}catch{status.textContent='We couldn’t save that strip. Please try again.'}finally{button.disabled=false}});
